-- Consulta 1
SELECT 
    c.CID,
    c.name,
    c.model,
    COUNT(e.EID) AS total_detections
FROM camera c
JOIN "event" e ON c.CID = e.CID
WHERE e.eTime >= NOW() - INTERVAL '30 days'
GROUP BY c.CID, c.name, c.model
ORDER BY total_detections DESC
LIMIT 3;


-- Consulta 2
SELECT 
    TO_CHAR(e.eTime AT TIME ZONE 'UTC', 'Day')    AS week_day,
    EXTRACT(DOW FROM e.eTime AT TIME ZONE 'UTC')  AS day_num,
    o.vehicle                                     AS vehicle_type,
    COUNT(o.OID)                                  AS total
FROM "object" o
JOIN "event"   e  ON o.EID  = e.EID
JOIN camera   c  ON e.CID  = c.CID
JOIN "location" u ON c.UID  = u.UID
WHERE u.zone_type  = 'peatonal_restringida'
  AND o.vehicle IS NOT NULL
GROUP BY week_day, day_num, o.vehicle
ORDER BY day_num, total DESC;


-- Consulta 3
SELECT 
    c.CID,
    c.name,
    c.model,
    ROUND(AVG(e.conf_level)::numeric, 4)    AS avg_confidence,
    COUNT(e.EID)                            AS total_events
FROM camera c
JOIN "event" e ON c.CID = e.CID
WHERE e.conf_level > 0.70
GROUP BY c.CID, c.name, c.model
ORDER BY avg_confidence DESC;


-- Consulta 4
SELECT 
    c.CID,
    c.name,
    c.model,
    c.state,
    MAX(e.eTime) AS last_event
FROM camera c
LEFT JOIN "event" e 
       ON c.CID = e.CID 
      AND e.eTime >= NOW() - INTERVAL '7 days'
WHERE e.EID IS NULL
GROUP BY c.CID, c.name, c.model, c.state
ORDER BY last_event ASC NULLS FIRST;


-- Consulta 5
SELECT 
    c.CID,
    c.name,
    a.severity,
    COUNT(a.AID) AS total_alerts
FROM camera  c
JOIN "event"  e ON c.CID = e.CID
JOIN alert  a ON e.EID = a.EID
WHERE a.aTime >= NOW() - INTERVAL '30 days'
GROUP BY c.CID, c.name, a.severity
ORDER BY c.name, total_alerts DESC;


-- Consulta 6
WITH referencia AS (
    SELECT em.embedding_vec
    FROM embedding em
    JOIN "object" o ON em.OID = o.OID
    ORDER BY em.EmID
    LIMIT 1
)
SELECT
    o.OID,
    o.object_type,
    o.color,
    o.vehicle,
    o.license_plate,
    e.eTime,
    c.name                                          AS camara,
    (em.embedding_vec <=> r.embedding_vec)          AS distancia_coseno
FROM embedding em
CROSS JOIN referencia r
JOIN "object"  o  ON em.OID  = o.OID
JOIN "event"   e  ON o.EID   = e.EID
JOIN camera    c  ON e.CID   = c.CID
WHERE em.OID != (SELECT em2.OID FROM embedding em2 ORDER BY em2.EmID LIMIT 1)
ORDER BY distancia_coseno ASC
LIMIT 5;


