    o.object_type,
    o.color,
    o.luggage,
    o.vehicle,
    o.license_plate,
    e.eTime,
    c.name                                      AS camera,
    l.zone_type,
    (em.embedding_vec <=> mv.v)                 AS distancia_coseno
FROM embedding em
JOIN reference_vector mv ON true
JOIN "object"  o  ON em.OID  = o.OID
JOIN "event"   e  ON o.EID   = e.EID
JOIN camera    c  ON e.CID   = c.CID
JOIN "location" l ON c.UID   = l.UID
WHERE e.eTime >= NOW() - INTERVAL '24 hours'
  AND (em.embedding_vec <=> mv.v) < 0.15
ORDER BY distancia_coseno ASC;